script:
frappe.ui.form.on('Estimator', {
    refresh(frm) {
        // Only run on first load — NOT on every change
        if (frm.doc.__islocal || !frm.doc.area) {
            populate_items(frm);
        }
    },
    area(frm) {
        trigger_rebuild(frm);
    },
    building_type(frm) {
        trigger_rebuild(frm);
    },
    room(frm) {
        trigger_rebuild(frm);
    },
    worker_salary(frm) {
        calculate_total(frm);
    }
});

// SINGLE REBUILD FUNCTION — NO DUPLICATES
function trigger_rebuild(frm) {
    if (frm._rebuilding) return;  // Prevent double call
    frm._rebuilding = true;

    frm.clear_table('estimate_items');
    frm.refresh_field('estimate_items');
    frm.set_value('total_estimate', 0);
    populate_items(frm);
}

frappe.ui.form.on('Estimate Items', {
    items(frm, cdt, cdn) {
        update_row(frm, cdt, cdn);
    },
    quantity(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, 'amount', flt(row.quantity) * flt(row.rate));
        calculate_total(frm);
    },
    rate(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        frappe.model.set_value(cdt, cdn, 'amount', flt(row.quantity) * flt(row.rate));
        calculate_total(frm);
    },
    estimate_items_remove(frm) {
        calculate_total(frm);
    }
});

function update_row(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row.items) return;

    frappe.db.get_value('Items', row.items, ['default_rate', 'uom', 'formula_for_quantity'], (r) => {
        if (!r || !r.formula_for_quantity) return;

        const mult = get_multiplier(frm.doc.building_type);
        const base_qty = flt(r.formula_for_quantity) * flt(frm.doc.area) * mult;

        frappe.model.set_value(cdt, cdn, 'rate', r.default_rate);
        frappe.model.set_value(cdt, cdn, 'uom', r.uom);
        frappe.model.set_value(cdt, cdn, 'quantity', base_qty);
        frappe.model.set_value(cdt, cdn, 'amount', base_qty * flt(r.default_rate));
        calculate_total(frm);
    });
}

function populate_items(frm) {
    // PREVENT DUPLICATES
    if (frm._rebuilding === false) return;

    if (!frm.doc.area || !frm.doc.building_type || frm.doc.building_type === 'None') {
        frm.clear_table('estimate_items');
        frm.refresh_field('estimate_items');
        apply_room_charge(frm, 0);
        frm._rebuilding = false;
        return;
    }

    const mult = get_multiplier(frm.doc.building_type);
    const area = flt(frm.doc.area);

    frm.clear_table('estimate_items');

    frappe.db.get_list('Items', {
        fields: ['name', 'uom', 'default_rate', 'formula_for_quantity'],
        filters: [['formula_for_quantity', '>', 0]],
        limit_page_length: 0
    }).then(r => {
        if (!r || r.length === 0) {
            apply_room_charge(frm, 0);
            frm._rebuilding = false;
            return;
        }

        let material_total = 0;

        r.forEach(item => {
            const base_qty = flt(item.formula_for_quantity) * area * mult;
            const amount = base_qty * flt(item.default_rate);
            material_total += amount;

            const row = frm.add_child('estimate_items');
            row.items = item.name;
            row.uom = item.uom;
            row.quantity = base_qty;
            row.rate = item.default_rate;
            row.amount = amount;
        });

        frm.refresh_field('estimate_items');
        apply_room_charge(frm, material_total);
        frm._rebuilding = false;  // Allow next rebuild
    }).catch(err => {
        console.error("Error:", err);
        apply_room_charge(frm, 0);
        frm._rebuilding = false;
    });
}

function apply_room_charge(frm, material_total) {
    const room_charge = get_room_charge(frm.doc.room, frm.doc.building_type);
    const worker_salary = flt(frm.doc.worker_salary || 0);
    const final_total = material_total + worker_salary + room_charge;

    frm.set_value('total_estimate', final_total);
    frm.refresh_field('total_estimate');
}

function calculate_total(frm) {
    let material_total = 0;
    (frm.doc.estimate_items || []).forEach(row => {
        material_total += flt(row.amount);
    });

    const room_charge = get_room_charge(frm.doc.room, frm.doc.building_type);
    const final_total = material_total + flt(frm.doc.worker_salary || 0) + room_charge;

    frm.set_value('total_estimate', final_total);
    frm.refresh_field('total_estimate');
}

function get_multiplier(type) {
    const map = {
        'House': 1,
        '2-Flat House': 2,
        '3-Flat House': 3,
        'Parking': 0.6,
        'Compound': 0.3,
        'Apartment': 4,
        'None': 1
    };
    return map[type] || 1;
}

function get_room_charge(room, building_type) {
    const residential = ['House', '2-Flat House', '3-Flat House', 'Apartment'];
    if (!residential.includes(building_type)) return 0;

    const base = 3;
    const extra = Math.max(0, flt(room) - base);
    return extra * 50000;
}

frappe.ui.form.on('Estimate_Items', {
    quantity: function(frm, cdt, cdn) {
        calculate_amount(frm, cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        calculate_amount(frm, cdt, cdn);
    }
});

function calculate_amount(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    row.amount = (row.quantity || 0) * (row.rate || 0);
    frappe.model.set_value(cdt, cdn, 'amount', row.amount);
}
